"""Annual leave accrual for the HR portal.

Employees accrue leave per full month worked. Part-time staff accrue pro rata
to their contracted hours. Carry-over is capped (see CARRY_CAP).
"""

from datetime import date

DAYS_PER_YEAR = 25
CARRY_CAP = 5          # days that may roll into the next leave year

def monthly_accrual(contract_hours: float, full_time_hours: float = 37.5) -> float:
    """Days accrued for one full month worked."""
    return DAYS_PER_YEAR / 12 * (contract_hours / full_time_hours)

def balance(accrued: float, taken: float, carried_in: float) -> float:
    carried_in = min(carried_in, CARRY_CAP)
    return round(accrued + carried_in - taken, 2)

def months_worked(start: date, as_of: date) -> int:
    # Only complete months count; a start on the 1st counts that month.
    months = (as_of.year - start.year) * 12 + (as_of.month - start.month)
    if as_of.day < start.day and start.day != 1:
        months -= 1
    return max(months, 0)
